def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    separators = [r for r, row in enumerate(grid) if all(v == 2 for v in row)]
    if not separators:
        return out

    sep = separators[0]
    top_rows = [r for r in range(sep) if any(grid[r][c] != 0 for c in range(w))]
    bottom_rows = [r for r in range(sep + 1, h) if any(grid[r][c] != 0 for c in range(w))]
    if not top_rows or not bottom_rows:
        return out

    top_color = next(grid[top_rows[0]][c] for c in range(w) if grid[top_rows[0]][c] != 0)
    bottom_color = next(grid[bottom_rows[-1]][c] for c in range(w) if grid[bottom_rows[-1]][c] != 0)
    if top_color != bottom_color:
        return out

    top_cols = {c for c, v in enumerate(grid[top_rows[0]]) if v == top_color}
    bottom_cols = {c for c, v in enumerate(grid[bottom_rows[-1]]) if v == bottom_color}
    for c in top_cols & bottom_cols:
        for r in range(top_rows[0] + 1, sep):
            if out[r][c] == 0:
                out[r][c] = 4
    return out
